import type {AddressInfo} from 'node:net';
import type {Express} from 'express';
import {WebSocket} from 'ws';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {answeringOrchestrator} from './wsTestSupport.js';
import type {SessionStore} from '../types/sessionStore.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';

const clients: WebSocket[] = [];
const servers: Array<ReturnType<typeof createServer>> = [];

afterEach(async () => {
  for (const client of clients.splice(0)) {
    await new Promise<void>(resolve => {
      client.once('close', resolve);
      client.terminate();
    });
  }
  for (const server of servers.splice(0)) await server.stop();
  await new Promise(resolve => setTimeout(resolve, 20));
});

// spec: specs/hal-engine-websocket-protocol/spec.md#4.4
it("delivers the authenticated user's conversation list over a real WebSocket", async () => {
  const seen: Array<{userId: string | number; options?: unknown}> = [];
  const store: SessionStore = new InMemorySessionStore();
  store.listFor = (userId, options) => {
    seen.push({userId, options});
    return [
      {
        sessionId: 's1',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-02T00:00:00.000Z'),
        entryCount: 2,
      },
    ];
  };
  const server = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'authenticated-user'}),
    sessionStore: store,
    orchestrator: answeringOrchestrator,
    history: {enabled: true},
  });
  servers.push(server);
  await server.start(0);
  const {port} = server.server.address() as AddressInfo;
  const client = new WebSocket(`ws://127.0.0.1:${port}/hal/ws`, [HAL_WS_SUBPROTOCOL, 'token']);
  clients.push(client);

  const frames = await new Promise<Array<Record<string, unknown>>>(resolve => {
    const received: Array<Record<string, unknown>> = [];
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Record<string, unknown>;
      if (frame.type === 'connected') {
        client.send(JSON.stringify({type: 'list_conversations', userId: 'another-user', limit: 10}));
        return;
      }
      received.push(frame);
      if (frame.type === 'conversation_list') resolve(received);
    });
  });

  expect({seen, frames}).toEqual({
    seen: [{userId: 'authenticated-user', options: {limit: 10, before: undefined}}],
    frames: [
      {
        type: 'conversation_list',
        conversations: [
          {
            sessionId: 's1',
            createdAt: '2026-01-01T00:00:00.000Z',
            updatedAt: '2026-01-02T00:00:00.000Z',
            entryCount: 2,
          },
        ],
      },
    ],
  });
});
  ]
}
```

The `sessionId` is a UUID v4 assigned by the server. It uniquely identifies this session; with resume enabled it outlives the connection and a reconnect can name it. The `examplePrompts` array contains example queries derived from the registered tool definitions, displayed in the client as clickable suggestions.

With resume enabled, the frame also carries `resumed`. On `resumed: true` it carries `entryCount`, and the server then replays the stored conversation before any other frame: one `entry_upsert` per entry at its own index, or an `entry_skip` for an entry a tool suppressed, so the client sees the conversation it saw live. When the connection named an id and was not resumed, the frame also carries `resumeFailure`: `expired` when the caller's own session aged out, `unknown` for every other case. With resume disabled none of these fields is present.

## 3. Message Format

All messages are JSON objects containing a REQUIRED `type` field that identifies the message kind. Additional fields depend on the message type.

```json
{
  "type": "<message_type>",
  ...
}
```

A client receiving a message with an unrecognized `type` SHOULD ignore it, so that additive protocol changes do not break older clients. The server does NOT ignore unknown types: it replies with an `error` carrying code `INVALID_MESSAGE` (Section 5.6). The public message unions preserve the session-listing frames ([validated by: keeps session listing frames in the public message unions](../../src/index.test.ts#L14)).

## 4. Client-to-Server Messages

### 4.1 user_message

Sends a user chat message. `user_message` is the only accepted type: the server previously also took `send_message`, which was removed before the first published release.

